         body='// TypedCart: fix one: short names from a list on the field\n@JsonTypeInfo(use = JsonTypeInfo.Id.NAME, property = "type")\n@JsonSubTypes({\n        @JsonSubTypes.Type(value = Note.Gift.class, name = "gift"),\n        @JsonSubTypes.Type(value = Note.Coupon.class, name = "coupon")})\nNote gift) {',
